Sdb* process_verneed_section(ELFOBJ *bin, Elf_(Shdr)* shdr, int sz) {
    if (!bin || !shdr || sz <= 0) {
        return NULL;
    }

    Sdb *sdb = sdb_new0();
    if (!sdb) {
        return NULL;
    }

    void *data = elf_getdata(bin, shdr);
    if (!data) {
        sdb_free(sdb);
        return NULL;
    }

    Elf_(Verneed) *verneed = (Elf_(Verneed)*)data;
    Elf_(Verneed) *end = (Elf_(Verneed*)((char*)data + sz));

    while ((char*)verneed < (char*)end) {
        for (int i = 0; i < verneed->vn_cnt; i++) {
            Elf_(VerneedEnt) *vna = &verneed->vna[i];
            char *version_name = elf_strptr(bin, shdr->sh_link, vna->vna_name);
            if (!version_name) {
                sdb_free(sdb);
                return NULL;
            }

            char key[256];
            snprintf(key, sizeof(key), "version.%s", version_name);
            sdb_num_set(sdb, key, 1, 0);
        }

        verneed = (Elf_(Verneed*)((char*)verneed + verneed->vn_next));
    }

    return sdb;
}

Sdb* process_verneed_section(ELFOBJ *bin, Elf_(Shdr)* shdr, int sz) {
    if (!bin || !shdr || sz <= 0) {
        return NULL;
    }

    Sdb *sdb = sdb_new0();
    if (!sdb) {
        return NULL;
    }

    void *data = elf_getdata(bin, shdr, &sz);
    if (!data) {
        sdb_free(sdb);
        return NULL;
    }

    Elf_(Verneed) *verneed = data;
    size_t offset = 0;
    while (offset < sz) {
        Elf_(Verneed) *vn = (Elf_(Verneed*) *)((char*)data + offset);
        for (int i = 0; i < vn->vn_cnt; i++) {
            Elf_(Verneed) *ve = (Elf_(Verneed*) *)((char*)vn + vn->vn_offset + i * sizeof(Elf_(Verneed)));
            char *version_name = (char*)data + ve->vna_name;
            char *aux_name = (char*)data + ve->vna_name + ve->vna_next;
            char key[256];
            snprintf(key, sizeof(key), "%s:%s", version_name, aux_name);
            sdb_set(sdb, key, NULL, 0);
        }
        offset += vn->vn_next;
    }

    return sdb;
}

Sdb* store_version_info(ELFOBJ *bin, Elf_Shdr *shdr, int sz) {
    if (!bin || !shdr || sz <= 0) {
        return NULL;
    }

    size_t num_entries;
    Elf_Verneed *verneed;
    Elf_Vernaux *vernaux;
    Sdb *sdb = sdb_new0();
    if (!sdb) {
        return NULL;
    }

    verneed = (Elf_Verneed*) sdb_malloc(bin, shdr->sh_offset, sz);
    if (!verneed) {
        sdb_free(sdb);
        return NULL;
    }

    for (num_entries = 0; num_entries < verneed->vn_cnt; num_entries++) {
        vernaux = (Elf_Vernaux*)((size_t)verneed + sizeof(Elf_Verneed) + num_entries * sizeof(Elf_Vernaux));
        if (verneed->vn_version != 1 || vernaux->vna_version != 1) {
            sdb_free(sdb);
            free(verneed);
            return NULL;
        }
        const char *version_name = sdb_get_string(bin, shdr, vernaux->vna_name);
        if (!version_name) {
            sdb_free(sdb);
            free(verneed);
            return NULL;
        }

        if (!sdb_num_put(sdb, version_name, (ut64)verneed->vn_other)) {
            sdb_free(sdb);
            free(verneed);
            return NULL;
        }
        verneed = (Elf_Verneed*)((size_t)verneed + verneed->vn_next);
    }

    free(verneed);
    return sdb;
}

Sdb* process_verneed_section(ELFOBJ *bin, Elf_Shdr *shdr, int sz) {
    if (!bin || !shdr || sz <= 0) {
        return NULL;
    }

    Sdb *db = sdb_new0();
    if (!db) {
        return NULL;
    }

    gstring *str = NULL;
    char *strtab = NULL;
    Elf_Verneed *verneed = NULL;
    Elf_Vernaux *vernaux = NULL;
    size_t count;
    int i, j;

    if (sz < sizeof(Elf_Verneed)) {
        sdb_free(db);
        return NULL;
    }

    verneed = (Elf_Verneed*)elf_getdata(bin, shdr, sz);
    if (!verneed) {
        sdb_free(db);
        return NULL;
    }

    strtab = elf_get_str_section(bin, shdr->sh_link, &count);
    if (!strtab) {
        sdb_free(db);
        return NULL;
    }

    for (i = 0; i < verneed->vn_cnt; i++) {
        vernaux = (Elf_Vernaux*)((char*)verneed + verneed->vn_next);
        for (j = 0; j < vernaux->vna_cnt; j++) {
            char key[256];
            snprintf(key, sizeof(key), "version.%d.%d", i, j);

            str = gstring_new(NULL);
            if (!str) {
                gstring_free(str);
                sdb_free(db);
                free(strtab);
                return NULL;
            }

            gstring_printf(str, "%s", strtab + vernaux->vna_name);
            sdb_put(db, key, str->buf, 0);
            gstring_free(str);
            vernaux = (Elf_Vernaux*)((char*)vernaux + vernaux->vna_next);
        }
        verneed = (Elf_Verneed*)((char*)verneed + verneed->vn_next);
    }

    free(strtab);
    return db;
}

Sdb* store_version_info(ELFOBJ* bin, Elf_(Shdr)* shdr, int sz) {
    if (!bin || !shdr || sz <= 0) {
        return NULL;
    }

    Sdb* sdb = sdb_new0();
    if (!sdb) {
        return NULL;
    }

    gstring* str = NULL;
    char* name = NULL;
    Elf_(Ptr) p = 0;
    Elf_(Word) cnt = 0;

    if (!elf_getshdrstrndx(bin->elf, &cnt)) {
        goto error;
    }

    if (!(name = elf_strptr(bin->elf, cnt, shdr->sh_name))) {
        goto error;
    }

    if ((p = (Elf_(Ptr))malloc(sz)) == NULL) {
        goto error;
    }

    if (elf_fill_mem(bin, (void*)p, shdr, sz) < 0) {
        goto error;
    }

    Elf_(Word) i = 0;
    while (i < sz) {
        Elf_Verneed* vn = (Elf_Verneed*)(&((Elf_Verneed*)p)[i / sizeof(Elf_Verneed)]);
        if (vn->vn_version != 1) {
            goto error;
        }

        for (Elf_(Word) j = 0; j < vn->vn_cnt; j++) {
            Elf_Verneed_Entry* vne = (Elf_Verneed_Entry*)(&((Elf_Verneed_Entry*)p)[(i + vn->vn_offset + j * sizeof(Elf_Verneed_Entry)) / sizeof(Elf_Verneed_Entry)]);
            if (vne->vna_next == 0) {
                continue;
            }

            Elf_Verneed_Entry* aux = (Elf_Verneed_Entry*)(&((Elf_Verneed_Entry*)p)[(i + vn->vn_offset + j * sizeof(Elf_Verneed_Entry)) / sizeof(Elf_Verneed_Entry) + 1]);
            char* version = elf_strptr(bin->elf, vn->vn_file, vne->vna_name);

            if (!version) {
                goto error;
            }

            str = gstring_new("");
            gstring_printf(str, "%s@%s", name, version);
            sdb_set(sdb, str->buf, version, 0);
            gstring_free(str);
        }

        i += vn->vn_next;
        if (i >= sz) {
            break;
        }
    }

    return sdb;

error:
    if (sdb) {
        sdb_free(sdb);
    }
    if (p) {
        free(p);
    }
    return NULL;
}
